class Solution {
public:
    int maximumLength(vector<int>& nums, int k) {
        vector<vector<int>> dp(k, vector<int>(k, 0));
        int ans = 0;
        for (int x : nums) {
            int r = (x % k + k) % k;
            for (int target = 0; target < k; ++target) {
                int prev = (target - r + k) % k;
                dp[r][target] = dp[prev][target] + 1;
                if (dp[r][target] > ans) ans = dp[r][target];
            }
        }
        return ans;
    }
};

