var maximumLength = function(nums, k) {
    const dp = Array.from({ length: k }, () => new Int32Array(k));
    let ans = 0;
    for (const x of nums) {
        const r = (x % k + k) % k;
        for (let target = 0; target < k; ++target) {
            const prev = (target - r + k) % k;
            dp[r][target] = dp[prev][target] + 1;
            if (dp[r][target] > ans) ans = dp[r][target];
        }
    }
    return ans;
};
